/**
 * engine-server/pipeline/phase-b/ammo-injector.ts — 弹药注入器
 *
 * V1.3 两轮注入架构：
 *   Round 1: matchAmmo(taskDef) → 行业事实弹药，Phase A 前注入（匹配 taskDef 关键词）
 *   Round 2: matchOrgAmmo(teamStructure) → 组织事实弹药，Phase A 后注入（匹配团队结构属性）
 *
 * 注入策略：约束关键词匹配（行业）+ 结构属性匹配（组织）
 * 注入位置：Round 1 在 Phase A prompt，Round 2 在 Phase B prompt
 *
 * @date 2026-05-14 (初始) / 2026-05-15 (两轮架构)
 */
import { type AmmoEntry } from './ammo-depot';
import type { TaskDefinitionDTO, TeamStructureBlue } from '../../types';
/**
 * 从弹药库匹配与任务约束相关的条目。
 *
 * @param taskDef - 任务定义
 * @param maxEntries - 最大返回条目数（避免 prompt 过长）
 * @returns 匹配到的弹药条目列表
 */
export declare function matchAmmo(taskDef: TaskDefinitionDTO, maxEntries?: number): AmmoEntry[];
/**
 * 将匹配到的弹药条目格式化为 prompt 注入文本。
 *
 * @param entries - 匹配到的弹药条目
 * @returns 格式化后的 prompt 注入文本
 */
export declare function formatAmmoForPrompt(entries: AmmoEntry[]): string;
/**
 * 一站式弹药注入：匹配 + 格式化。
 * Round 1 — 行业事实，Phase A 前调用。
 *
 * @param taskDef - 任务定义
 * @returns 弹药注入文本（无匹配时返回空字符串）
 */
export declare function injectAmmo(taskDef: TaskDefinitionDTO): string;
/**
 * 从弹药库匹配组织事实类型的弹药条目。
 *
 * 匹配策略：不按行业关键词，而按团队结构属性（角色数、治理层分布、
 * 是否跨文化、是否依赖外部等）。TeamStructureBlue 是 Phase A 的产出。
 *
 * @param teamStructure - Phase A 产出的团队结构
 * @param taskDef - 任务定义（辅助判断跨文化/外部依赖等）
 * @param maxEntries - 最大返回条目数
 * @returns 匹配到的组织弹药条目列表
 */
export declare function matchOrgAmmo(teamStructure: TeamStructureBlue, taskDef: TaskDefinitionDTO, maxEntries?: number): AmmoEntry[];
/**
 * Round 2 一站式弹药注入：匹配 + 格式化。
 *
 * @param teamStructure - Phase A 产出的团队结构
 * @param taskDef - 任务定义
 * @returns 弹药注入文本（无匹配时返回空字符串）
 */
export declare function injectOrgAmmo(teamStructure: TeamStructureBlue, taskDef: TaskDefinitionDTO): string;
